"""Read the supplied original's portal sprite transforms; never execute it."""
from pathlib import Path
from inspect_original import Original


def literal(value):
    number = format(value, '.6g')
    return number + ('.0f' if '.' not in number and 'e' not in number else 'f')


def main():
    original = Original()
    lines = [
        '// Generated by game/tools/import_portal_visual.py from the supplied original.',
        '// Portal.refreshV2SpritesByIdxFrame: 40 poses at 60 Hz, 24 child sprites.',
        '#pragma once',
        '#include "engine/core/geometry/vector2.h"',
        '#include <algorithm>',
        '#include <array>',
        '#include <cmath>',
        '#include <cstdint>',
        'namespace game::play {',
        'struct PortalPartPose {elysia::core::Vector2 offset,scale;float rotation;std::uint8_t alpha;};',
    ]
    for name, address in [('Entrance', 0x1a6e78), ('Exit', 0x1a1478)]:
        lines.append(f'// ARM table at 0x{address:x}; converted from local Y-up to centered Y-down.')
        lines.append(f'inline constexpr std::array<std::array<PortalPartPose,24>,40> kPortal{name}{{{{')
        for frame in range(40):
            lines.append('    {{')
            for part in range(24):
                x, y, sx, sy, rotation, alpha = original.unpack('<5fB', address + (frame * 24 + part) * 24)
                lines.append('        {{' + literal(x - 32) + ',' + literal(-32 - y) + '},{' +
                             literal(sx) + ',' + literal(sy) + '},' + literal(rotation) + ',' + str(alpha) + '},')
            lines.append('    }},')
        lines.append('}};')
    lines.extend([
        'inline const std::array<PortalPartPose,24>& portal_pose(double seconds,bool exit) {',
        '    const auto frame=static_cast<std::size_t>(std::floor(std::fmod(std::max(0.,seconds)*60.,40.)));',
        '    return (exit?kPortalExit:kPortalEntrance)[frame];',
        '}',
        '}',
    ])
    target = Path(__file__).resolve().parents[1] / 'gameplay/portal_visual.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
